1698	            DynamicPrintConfig new_conf = *m_config;
1699	            if (dialog.ShowModal() == wxID_NO) {
1700	                new_conf.set_key_value("support_filament", new ConfigOptionInt(0));
1701	                m_config_manipulation.apply(m_config, &new_conf);
1702	                on_value_change(opt_key, 0);
1703	            }
1704	            wxGetApp().plater()->update();
1705	        }
1706	    }
1707	
1708	    // BBS popup a message to ask the user to set optimum parameters for support interface if support materials are used
1709	    if (opt_key == "support_interface_filament") {
1710	        int filament_id           = m_config->opt_int("support_filament") - 1;
1711	        int interface_filament_id = m_config->opt_int("support_interface_filament") - 1; // the displayed id is based from 1, while internal id is based from 0
1712	        if ((is_support_filament(interface_filament_id, false) &&
1713	             !(m_config->opt_float("support_top_z_distance") == 0 && m_config->opt_float("support_interface_spacing") == 0 &&
1714	               m_config->opt_enum<SupportMaterialInterfacePattern>("support_interface_pattern") == SupportMaterialInterfacePattern::smipRectilinearInterlaced)) ||
1715	            (is_soluble_filament(interface_filament_id) && !is_soluble_filament(filament_id))) {
1716	            wxString msg_text;
1717	            if (!is_soluble_filament(interface_filament_id)) {
1718	                msg_text = _L("When using support material for the support interface, we recommend the following settings:\n"
1719	                              "0 top Z distance, 0 interface spacing, interlaced rectilinear pattern and disable independent support layer height.");
1720	                msg_text += "\n\n" + _L("Change these settings automatically?\n"
1721	                                        "Yes - Change these settings automatically\n"
1722	                                        "No  - Do not change these settings for me");
1723	            } else {
1724	                msg_text = _L("When using soluble material for the support interface, we recommend the following settings:\n"
1725	                              "0 top Z distance, 0 interface spacing, interlaced rectilinear pattern, disable independent support layer height\n"
1726	                              "and use soluble materials for both support interface and support base.");
1727	                msg_text += "\n\n" + _L("Change these settings automatically?\n"
1728	                                        "Yes - Change these settings automatically\n"
1729	                                        "No  - Do not change these settings for me");
1730	            }
