1768	
1769	    if (opt_key == "sparse_infill_rotate_template") {
1770	        // Orca: show warning dialog if rotate template for solid infill if not support
1771	        const auto _sparse_infill_pattern = m_config->option<ConfigOptionEnum<InfillPattern>>("sparse_infill_pattern")->value;
1772	        bool       is_safe_to_rotate      = _sparse_infill_pattern == ipRectilinear || _sparse_infill_pattern == ipLine ||
1773	                                 _sparse_infill_pattern == ipZigZag || _sparse_infill_pattern == ipCrossZag ||
1774	                                 _sparse_infill_pattern == ipLockedZag;
1775	        
1776	        auto new_value = boost::any_cast<std::string>(value);
