1781	            wxString msg_text = _(
1782	                L("Infill patterns are typically designed to handle rotation automatically to ensure proper printing and achieve their "
1783	                  "intended effects (e.g., Gyroid, Cubic). Rotating the current sparse infill pattern may lead to insufficient support. "
1784	                  "Please proceed with caution and thoroughly check for any potential printing issues. "
1785	                  "Are you sure you want to enable this option?"));
1786	            msg_text += "\n\n" + _(L("Are you sure you want to enable this option?"));
1787	            MessageDialog dialog(wxGetApp().plater(), msg_text, "", wxICON_WARNING | wxYES | wxNO);
