1800	
1801	    if(opt_key=="layer_height"){
1802	        auto min_layer_height_from_nozzle=m_preset_bundle->full_config().option<ConfigOptionFloats>("min_layer_height")->values;
1803	        auto max_layer_height_from_nozzle=m_preset_bundle->full_config().option<ConfigOptionFloats>("max_layer_height")->values;
1804	        auto layer_height_floor = *std::min_element(min_layer_height_from_nozzle.begin(), min_layer_height_from_nozzle.end());
1805	        auto layer_height_ceil  = *std::max_element(max_layer_height_from_nozzle.begin(), max_layer_height_from_nozzle.end());
1806	        const auto lh = m_config->opt_float("layer_height");
1807	        bool exceed_minimum_flag = lh < layer_height_floor;
1808	        bool exceed_maximum_flag = lh > layer_height_ceil;
1809	
1810	        if (exceed_maximum_flag || exceed_minimum_flag) {
1811	            if (lh < EPSILON) {
1812	                auto          msg_text = _(L("Layer height is too small.\nIt will set to min_layer_height\n"));
1813	                MessageDialog dialog(wxGetApp().plater(), msg_text, "", wxICON_WARNING | wxOK);
1814	                dialog.SetButtonLabel(wxID_OK, _L("OK"));
1815	                dialog.ShowModal();
1816	                auto new_conf = *m_config;
1817	                new_conf.set_key_value("layer_height", new ConfigOptionFloat(layer_height_floor));
1818	                m_config_manipulation.apply(m_config, &new_conf);
1819	            } else {
1820	                wxString msg_text = _(L("Layer height exceeds the limit in Printer Settings -> Extruder -> Layer height limits, "
1821	                                        "this may cause printing quality issues."));
1822	                msg_text += "\n\n" + _(L("Adjust to the set range automatically?\n"));
1823	                MessageDialog dialog(wxGetApp().plater(), msg_text, "", wxICON_WARNING | wxYES | wxNO);
1824	                dialog.SetButtonLabel(wxID_YES, _L("Adjust"));
1825	                dialog.SetButtonLabel(wxID_NO, _L("Ignore"));
1826	                auto answer   = dialog.ShowModal();
1827	                auto new_conf = *m_config;
1828	                if (answer == wxID_YES) {
1829	                    if (exceed_maximum_flag)
1830	                        new_conf.set_key_value("layer_height", new ConfigOptionFloat(layer_height_ceil));
