#pragma once

// Listens to OrcaSlicer's own dialogs. Every Orca dialog opens through
// DPIAware::ShowModal, which first asks answer_modal (GUI_Utils.hpp); that
// hands the dialog to the listeners registered here, innermost first. A
// listener answers the dialog, and it is never shown, or passes it on; when
// every listener has passed, Orca shows it as usual.
//
// A listener learns what the window itself shows: its title, its message and
// which of the standard buttons it offers. Nothing is matched against the
// words, which are Orca's and in the interface language.
//
// GUI thread only.

#include "Workspace.hpp"

#include <functional>
#include <optional>
#include <string>
#include <vector>

class wxWindow;

namespace Slic3r::GUI::JusPrin::Workspace {

struct DialogFacts
{
    std::string title;
    std::string text;
    bool        ok{false}, yes{false}, no{false}, cancel{false};
    // Orca's STEP import settings, recognised by type: its Cancel abandons
    // the whole load, so it is the one dialog whose least change is OK.
    bool        step_import{false};
};

DialogFacts read_dialog(wxWindow& dialog);

// The choice that changes least, from the buttons alone: No, else Cancel,
// else OK, else Yes (Orca offers a lone Yes only where it acts regardless).
// A dialog with none of them is cancelled and marked unrecognised.
OrcaMessage least_change_answer(const DialogFacts& facts, int& answer);

class ScopedDialogListener
{
public:
    // Returns the id ShowModal would have returned, or nothing to pass.
    using Listener = std::function<std::optional<int>(wxWindow& dialog, const DialogFacts& facts)>;

    explicit ScopedDialogListener(Listener listener);
    ~ScopedDialogListener();
    ScopedDialogListener(const ScopedDialogListener&)            = delete;
    ScopedDialogListener& operator=(const ScopedDialogListener&) = delete;

private:
    friend bool dispatch_dialog(wxWindow& dialog, int& answer);
    Listener              m_listener;
    ScopedDialogListener* m_outer{nullptr};
};

// Answers every dialog with the least change and writes each one down: the
// file load's listener, and the safety net around a tool's Orca calls.
class ScopedLeastChangeAnswers
{
public:
    explicit ScopedLeastChangeAnswers(bool prefer_cancel = false);
    const std::vector<OrcaMessage>& messages() const { return m_messages; }
    std::vector<OrcaMessage>        take_messages() { return std::move(m_messages); }
    void                            add_message(OrcaMessage message) { m_messages.push_back(std::move(message)); }

private:
    std::vector<OrcaMessage> m_messages;
    ScopedDialogListener     m_listener; // after m_messages, which it writes to
};

} // namespace Slic3r::GUI::JusPrin::Workspace

#pragma once

#include "Workspace.hpp"

#include <algorithm>
#include <charconv>
#include <limits>
#include <cctype>
#include <numeric>
#include <string_view>
#include <tuple>

namespace Slic3r::GUI::JusPrin::Workspace {

// The settings no tool changes, in any scope. Every other setting a scope
// holds is writable: OrcaSettings refuses, for any key, the values that
// would make Orca ask or that it would not print, and apply reports whatever
// Orca rewrote. A key belongs here for what a wrong value does outside the
// print, not because nobody has needed it yet.
inline bool blocked_setting(const std::string& key)
{
    constexpr std::string_view keys[] = {
        // Runs a program on this computer when G-code is exported.
        "post_process",
        // Where a printer is on the network, and how to sign in to it.
        "host_type", "print_host", "print_host_webui", "printhost_port", "printhost_apikey", "printhost_user",
        "printhost_password", "printhost_authorization_type", "printhost_cafile", "printhost_ssl_ignore_revoke",
        "bbl_use_printhost", "printer_agent", "flashforge_serial_number",
        // Which preset this is, what it inherits from and what it fits. A
        // different value breaks the preset rather than tuning it.
        "inherits", "compatible_printers", "compatible_printers_condition", "compatible_prints",
        "compatible_prints_condition", "print_extruder_id", "print_extruder_variant", "filament_extruder_variant",
        "printer_extruder_id", "printer_extruder_variant", "extruder_variant_list", "default_print_profile",
        "default_filament_profile", "upward_compatible_machine", "printer_technology",
        // The printer's hardware: its model, bed, nozzles and extruders.
        // These decide which filaments and processes fit and how many values
        // a per-extruder setting holds; they change with a different printer
        // or nozzle, through printer_setup or printer_change.
        "printer_model", "printer_variant", "printer_structure", "printable_area", "extruder_printable_area",
        "bed_exclude_area", "bed_custom_texture", "bed_custom_model", "nozzle_diameter", "nozzle_type",
        "nozzle_volume", "default_nozzle_volume_type", "nozzle_flush_dataset", "extruder_type", "extruder_offset",
        "single_extruder_multi_material", "support_parallel_printheads", "parallel_printheads_count",
        "parallel_printheads_bed_exclude_areas", "master_extruder_id", "physical_extruder_map", "pellet_modded_printer"};
    return std::find(std::begin(keys), std::end(keys), key) != std::end(keys);
}

// The caller checks that the key is one its scope holds.
inline bool writable_setting(const std::string& key) { return !blocked_setting(key); }

inline const char* scope_name(SettingsScope scope)
{
    switch (scope) {
    case SettingsScope::Process: return "process";
    case SettingsScope::Object: return "object";
    case SettingsScope::Filament: return "filament";
    case SettingsScope::Printer: return "printer";
    }
    return "process";
}

