161	// ConfigManipulation resets support_style to default, silently, when it does
162	// not fit the support type. A patch that would be rewritten that way is
163	// refused with the styles that fit, rather than accepted and then changed.
164	inline void check_support_style(const DynamicPrintConfig& config, const std::map<std::string, std::string>& patch,
165	                                SettingsPreview& result)
166	{
167	    if (!config.opt_bool("enable_support") ||
168	        (!patch.count("support_style") && !patch.count("support_type") && !patch.count("enable_support")))
169	        return;
170	    const bool tree = is_tree(config.opt_enum<SupportType>("support_type"));
171	    const std::vector<SupportMaterialStyle> fitting = tree ?
172	        std::vector<SupportMaterialStyle>{smsDefault, smsTreeSlim, smsTreeStrong, smsTreeHybrid, smsTreeOrganic} :
173	        std::vector<SupportMaterialStyle>{smsDefault, smsGrid, smsSnug};
174	    const auto style = config.opt_enum<SupportMaterialStyle>("support_style");
175	    if (std::find(fitting.begin(), fitting.end(), style) != fitting.end())
176	        return;
177	    std::vector<std::string> allowed;
