// Audit against ConfigManipulation::update_print_fff_config. These are every
// active modal predicate, including unrelated pre-existing invalid values:
// update() evaluates the entire config after any allowed batch. Keep refusal
// here; the live normalizer remains unchanged and owns its UI behavior.
inline void check_process_dialogs(const DynamicPrintConfig& config, SettingsPreview& result)
{
    const auto block = [&](bool condition, const std::string& key, const std::string& message) {
        if (condition) result.issues.push_back({key, "incompatible_settings", message});
    };
    const double height = config.opt_float("layer_height");
    const auto& printer = wxGetApp().preset_bundle->printers.get_edited_preset().config;
    const double maximum = printer.opt_float("max_layer_height", 0);
    if (height < EPSILON)
        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height is below Orca's minimum.", {}, {}, EPSILON, {}});
    if (maximum > 0.2 && height > maximum + EPSILON)
        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height exceeds the printer maximum.", {}, {}, {}, maximum});
    for (const auto* key : {"ironing_spacing", "support_ironing_spacing"})
        block(config.opt_float(key) < 0.05, key, "Ironing spacing would open Orca's correction dialog; correct it first.");
    block(config.opt_float("initial_layer_print_height") < EPSILON, "initial_layer_print_height", "Initial layer height would open Orca's correction dialog.");
    for (const auto* key : {"xy_hole_compensation", "xy_contour_compensation"})
        block(std::abs(config.opt_float(key)) > 2, key, "XY compensation would open Orca's correction dialog.");
    block(config.opt_float("elefant_foot_compensation") > 1, "elefant_foot_compensation", "Elephant foot compensation would open Orca's correction dialog.");
    if (config.opt_bool("spiral_mode")) {
        // The values Orca's spiral dialog sets when answered Yes. The refusal
        // names the ones that differ, for a patch to send with it.
        std::string needed;
        const auto need = [&](bool met, const char* key, const char* value) {
            if (!met) needed += (needed.empty() ? "" : ", ") + std::string(key) + "=" + value;
        };
        need(config.opt_int("wall_loops") == 1, "wall_loops", "1");
        need(config.opt_int("top_shell_layers") == 0, "top_shell_layers", "0");
        need(config.option<ConfigOptionPercent>("sparse_infill_density")->value == 0, "sparse_infill_density", "0%");
        need(!config.opt_bool("enable_support"), "enable_support", "0");
        need(config.opt_int("enforce_support_layers") == 0, "enforce_support_layers", "0");
        need(!config.opt_bool("detect_thin_wall"), "detect_thin_wall", "0");
        need(!config.opt_bool("overhang_reverse"), "overhang_reverse", "0");
        need(config.opt_enum<TimelapseType>("timelapse_type") == tlTraditional, "timelapse_type", "0");
        need(!config.opt_bool("enable_wrapping_detection"), "enable_wrapping_detection", "0");
        block(!needed.empty(), "spiral_mode",
              "Spiral vase (spiral_mode=1) needs " + needed + " in the same patch. Otherwise spiral_mode must be 0.");
    }
    block(config.opt_bool("alternate_extra_wall") && config.opt_enum<EnsureVerticalShellThickness>("ensure_vertical_shell_thickness") == evstAll,
        "alternate_extra_wall", "Alternate extra wall conflicts with ensure_vertical_shell_thickness=all.");
    block(config.opt_enum<SeamScarfType>("seam_slope_type") != SeamScarfType::None && config.get_abs_value("seam_slope_start_height") >= height,
        "layer_height", "Layer height conflicts with seam_slope_type and seam_slope_start_height; scarf start height must be below layer height.");
    block(config.opt_float("infill_lock_depth") > config.opt_float("skin_infill_depth"), "infill_lock_depth", "Infill lock depth exceeds skin_infill_depth.");
    block(config.opt_enum<FuzzySkinMode>("fuzzy_skin_mode") != FuzzySkinMode::Displacement &&
        config.opt_enum<PerimeterGeneratorType>("wall_generator") != PerimeterGeneratorType::Arachne,
        "fuzzy_skin_mode", "This fuzzy skin mode requires wall_generator=arachne.");
}

// ConfigManipulation resets support_style to default, silently, when it does
// not fit the support type. A patch that would be rewritten that way is
// refused with the styles that fit, rather than accepted and then changed.
inline void check_support_style(const DynamicPrintConfig& config, const std::map<std::string, std::string>& patch,
                                SettingsPreview& result)
{
    if (!config.opt_bool("enable_support") ||
        (!patch.count("support_style") && !patch.count("support_type") && !patch.count("enable_support")))
        return;
    const bool tree = is_tree(config.opt_enum<SupportType>("support_type"));
    const std::vector<SupportMaterialStyle> fitting = tree ?
        std::vector<SupportMaterialStyle>{smsDefault, smsTreeSlim, smsTreeStrong, smsTreeHybrid, smsTreeOrganic} :
        std::vector<SupportMaterialStyle>{smsDefault, smsGrid, smsSnug};
    const auto style = config.opt_enum<SupportMaterialStyle>("support_style");
    if (std::find(fitting.begin(), fitting.end(), style) != fitting.end())
        return;
    std::vector<std::string> allowed;
    for (SupportMaterialStyle candidate : fitting)
        allowed.push_back(ConfigOptionEnum<SupportMaterialStyle>(candidate).serialize());
    result.issues.push_back({"support_style", "invalid_setting_value",
                             std::string("With ") + (tree ? "tree" : "normal") +
                                 " supports, support_style must be one of the allowed values; OrcaSlicer would reset it to default.",
                             allowed});
}

inline bool process_tab_toggles_options(Tab& tab)
{
    // Public field lookup identifies the active page without adding an Orca
    // accessor. TabPrint::update skips toggles on an absent/Dependencies page.
    for (const auto& key : Preset::print_options()) {
        if (tab.get_field(key)) {
            Page* page = nullptr;
            tab.get_field(key, &page);
            return page && page->title() != "Dependencies";
        }
    }
    return false;
}

inline void predict_process_normalization(DynamicPrintConfig& config)
{
    // The modal predicates above were checked first. Execute Orca's own
    // normalization on the clone with no presentation callbacks; don't keep
    // a duplicate table of dependent values or infill-pattern capabilities.
    ConfigManipulation normalizer([] {}, [](const std::string&, bool, int) {}, {}, {});
    auto& bundle = *wxGetApp().preset_bundle;
    const auto& selected = bundle.prints.get_selected_preset();
    normalizer.initialize_support_material_overhangs_queried(!selected.is_system && !selected.is_dirty &&
        config.opt_bool("enable_support") && !config.opt_bool("detect_overhang_wall"));
    normalizer.set_is_BBL_Printer(bundle.is_bbl_vendor());
    normalizer.update_print_fff_config(&config, true, false);
    if (process_tab_toggles_options(*wxGetApp().get_tab(Preset::TYPE_PRINT)))
        normalizer.toggle_print_fff_options(&config, true);
}

// The filament tab's dialogs, refused before they could open.
// ConfigManipulation::check_filament_max_volumetric_speed resets a speed
// below 0.5 behind a warning on every load; Tab::save_preset asks to continue
// when a first-layer temperature is further than Tab::
// validate_filament_temperature_pairs allows from the other layers' (30 °C
// on the nozzle, 15 °C on a plate), both above zero.
inline void check_filament_dialogs(const DynamicPrintConfig& config, bool saving, SettingsPreview& result)
{
    if (config.has("filament_max_volumetric_speed") && config.opt_float("filament_max_volumetric_speed", 0) < 0.5)
        result.issues.push_back({"filament_max_volumetric_speed", "invalid_setting_value",
                                 "Orca resets a max volumetric speed below 0.5 to 0.5.", {}, {}, 0.5, {}});
    if (!saving)
        return;
    std::vector<std::tuple<std::string, std::string, int>> pairs{{"nozzle_temperature_initial_layer", "nozzle_temperature", 30}};
    for (int bed = int(btPC); bed < int(btCount); ++bed) {
        const std::string first = get_bed_temp_1st_layer_key(BedType(bed)), other = get_bed_temp_key(BedType(bed));
        if (!first.empty() && !other.empty())
            pairs.emplace_back(first, other, 15);
    }
    for (const auto& [first_key, other_key, limit] : pairs) {
        const auto* first = config.option<ConfigOptionInts>(first_key);
        const auto* other = config.option<ConfigOptionInts>(other_key);
        if (first == nullptr || other == nullptr || first->values.empty() || other->values.empty())
            continue;
        const int a = first->get_at(0), b = other->get_at(0);
        if (a > 0 && b > 0 && std::abs(a - b) > limit)
            result.issues.push_back({first_key, "incompatible_settings",
                                     first_key + " and " + other_key + " may differ by at most " + std::to_string(limit) +
                                         " °C; Orca asks before saving a larger difference."});
    }
}

// TabPrinter::toggle_options asks to turn wipe off, or firmware retraction
// off, when firmware retraction meets a wipe that retracts less than 100%
// first, on any extruder.
inline void check_printer_dialogs(const DynamicPrintConfig& config, SettingsPreview& result)
{
    if (!config.opt_bool("use_firmware_retraction"))
        return;
    const auto* wipe   = config.option<ConfigOptionBools>("wipe");
    const auto* before = config.option<ConfigOptionPercents>("retract_before_wipe");
    for (std::size_t index = 0; wipe != nullptr && before != nullptr && index < wipe->values.size(); ++index)
        if (wipe->get_at(index) && before->get_at(index) < 100.)
            return result.issues.push_back({"use_firmware_retraction", "incompatible_settings",
                                            "Firmware retraction with wipe needs retract_before_wipe at 100%; Orca asks to change one of them."});
}

inline PresetCollection& scope_collection(SettingsScope scope)
{
    PresetBundle& bundle = *wxGetApp().preset_bundle;
    return scope == SettingsScope::Filament ? static_cast<PresetCollection&>(bundle.filaments) :
           scope == SettingsScope::Printer  ? static_cast<PresetCollection&>(bundle.printers) :
                                              static_cast<PresetCollection&>(bundle.prints);
}

// A filament or printer preset named by a settings call, by the name Orca
// keys it by. Null when no preset a person could pick has that name.
inline const Preset* scope_preset(SettingsScope scope, const std::string& name)
{
    const Preset* preset = scope_collection(scope).find_preset(name, false);
    return preset != nullptr && preset->is_visible && !preset->is_default && preset->name == name ? preset : nullptr;
}

